\begin{theorem}[\lbl{Computed}, exact rational arithmetic]\label{thm:Mk0}
With $F$ a polynomial in $1-P_1$ and $P_2$ only,
\[
M_{105}\ge4.00206976,\qquad M_{102}\ge4.00271343,\qquad M_{5}\ge2.00410541 .
\]
\end{theorem}

\begin{theorem}[\lbl{Computed}, exact rational arithmetic]\label{thm:Mk}
\begin{gather*}
M_{105}\ge4.17427,\qquad M_{64}\ge4.00363,\qquad M_{58}\ge4.00927,\\
M_{56}\ge4.00519,\qquad M_{55}\ge4.00516,\qquad M_{54}\ge4.00238 .
\end{gather*}
The first two use all symmetric polynomials of degree $11$ and $12$
($195$ and $272$ coefficients). The others use the subspace spanned by
$(1-P_1)^aP^b$ with $b$ supported on even $j$, as in \cite[\S7]{Pol14b}, of
degree $16$, $18$, $20$ and $23$ ($307$, $471$, $707$ and $1236$ coefficients).
\end{theorem}

\begin{corollary}[end-to-end within this project]\label{cor:578}
Assuming the Bombieri--Vinogradov theorem and \cite[Prop.~4.2]{May15}, both
\lbl{Literature}, Theorems~\ref{thm:Mk} and~\ref{thm:lean} give
$H_1\le270$.
\end{corollary}

\begin{corollary}[end-to-end within this project]\label{cor:246}
Assuming the Bombieri--Vinogradov theorem and \cite[Thm.~3.12(i)]{Pol14b},
both \lbl{Literature}, Theorem~\ref{thm:Meps} and the Lean tuple $(50,246)$
of Theorem~\ref{thm:lean} give $H_1\le246$.
\end{corollary}

\begin{proposition}[\lbl{Computed}, floating point, discretised; not a rigorous bound]\label{prop:family}
Discretise $\Psi=\rho\cdot(L-\sigma+(k-1)u)$ with $\rho$ constant on cells of
an $N\times{}$(geometric) grid in $(S,u)$, impose the fiber conditions exactly
on the grid $\sigma\in\frac LN\mathbb Z$, and impose the pointwise condition
on all configurations of the grid of step $L/N$ (found by a knapsack oracle).
The convex optimum $B_N(k,\varepsilon)$, computed by cutting planes with an
exact convex solver at each step, is:
\begin{center}
\begin{tabular}{@{}lccccc@{}}
\toprule
$(k,\varepsilon)$ & $N=80$ & $N=120$ & $N=160$ & best weight known & $M_{k,\varepsilon}\ge$\\
\midrule
$(50,0)$    & 3.9919 & & & 3.9919 (Cor.~6.4) & 3.9274\\
$(50,1/25)$ & 4.1427 & 4.1420 & 4.1418 & 4.1458 (Thm.~\ref{thm:floor}) & 4.0012\\
$(30,1/4)$  & 4.0501 & 4.0345 & 4.0240 & 4.0021 (Thm.~\ref{thm:floor}) & --\\
\bottomrule
\end{tabular}
\end{center}
\end{proposition}

\begin{proposition}[\lbl{Computed}, exact rational arithmetic, two independent programs; versions 0.9 and 0.12]\label{prop:kin-capped}
Let $P$ be our cap-free optimiser of degree $22$ for $M_{48,15/506}$ ($1041$
coefficients, even power sums; certified Rayleigh quotient $3.9589046383$, so
$kJ/I=\frac{253}{250}\cdot3.9589046=4.0064115$ without caps), rounded to
$400$ significant bits per coefficient, and $T$ the support of \cite{Kin26}
above. Then
\[
\frac{48\,J_T(P\,1_T)}{I_T(P\,1_T)}=4.0060814208\ldots\ >\ 4 .
\]
\end{proposition}

\begin{proposition}[\lbl{Computed}, exact rational arithmetic; the capped numerator by two independent programs]\label{prop:sy-exact}
For the witness $P_U$ of \cite{SY26} and the support $T$ above:
\begin{enumerate}
\item $(98!)^2\,10^{192}\,5^{150}\,521^{50}\,I_0=I_{\mathrm{ref}}$ exactly;
\item $(99!)^2(26!)^2\,10^{196}\,5^{150}\,521^{50}\,J_T=J_{\mathrm{ref}}$ exactly,
where $J_T$ is the capped numerator;
\item hence $48J_T/I_0=1.000664921591\ldots>\frac{2001}{2000}$, i.e.\
$4.0026596864\ldots$ in our scaling. With the capped denominator,
$48J_T/I_T=4.0030988047\ldots$ ($I_T/I_0=0.99989031$). Without the caps,
$48J_0/I_0=4.0036348167\ldots$.
\end{enumerate}
\end{proposition}
